'use client'

import * as React from 'react'
import { cn } from "@/lib/utils"
import { format } from 'date-fns'
import type { DateRange, OnSelectHandler } from 'react-day-picker'

import { Button } from './button'
import { Calendar } from './calendar'
import { Popover, PopoverContent, PopoverTrigger } from './popover'

type DatePickerMode = 'single' | 'range'

type DatePickerValue = Date | DateRange | undefined

interface DatePickerProps {
  mode?: DatePickerMode
  value?: DatePickerValue
  defaultValue?: DatePickerValue
  onValueChange?: (value: DatePickerValue) => void
  placeholder?: string
  className?: string
  triggerClassName?: string
  contentClassName?: string
  calendarProps?: Omit<CalendarProps, 'mode' | 'selected' | 'onSelect'>
}

type CalendarProps = React.ComponentProps<typeof Calendar>

const formatSingle = (value: Date) => format(value, 'LLL dd, y')
const formatRange = (value: DateRange) => {
  if (value.from && value.to) {
    return `${format(value.from, 'LLL dd, y')} - ${format(value.to, 'LLL dd, y')}`
  }
  if (value.from) {
    return format(value.from, 'LLL dd, y')
  }
  return ''
}

function DatePicker({
  mode = 'single',
  value,
  defaultValue,
  onValueChange,
  placeholder = 'Date',
  className,
  triggerClassName,
  contentClassName,
  calendarProps,
}: DatePickerProps) {
  const isControlled = value !== undefined
  const [uncontrolled, setUncontrolled] = React.useState<DatePickerValue>(defaultValue)
  const selected = isControlled ? value : uncontrolled

  const handleChange = React.useCallback(
    (next: DatePickerValue) => {
      if (!isControlled) setUncontrolled(next)
      onValueChange?.(next)
    },
    [isControlled, onValueChange]
  )

  const handleSelect = React.useCallback<OnSelectHandler<DatePickerValue>>(
    (next) => handleChange(next),
    [handleChange]
  )

  const label = React.useMemo(() => {
    if (mode === 'range') {
      return selected && typeof selected === 'object' && 'from' in selected
        ? formatRange(selected as DateRange)
        : ''
    }
    return selected instanceof Date ? formatSingle(selected) : ''
  }, [mode, selected])

  return (
    <div data-slot="date-picker" className={cn('w-full', className)}>
      <Popover>
        <PopoverTrigger asChild data-slot="date-picker-trigger" className="w-full">
          <Button
            variant="outline"
            size="sm"
            className={cn(
              'bg-background border-input w-full justify-between px-3 text-sm font-normal outline-offset-0 outline-none focus-visible:outline-[3px]',
              triggerClassName
            )}
          >
            <svg
              width={16}
              height={16}
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="text-muted-foreground/80 -ms-1 shrink-0"
              aria-hidden="true"
            >
              <rect x="3" y="4" width="18" height="18" rx="2" />
              <path d="M8 2v4" />
              <path d="M16 2v4" />
              <path d="M3 10h18" />
            </svg>
            <span className={cn('truncate', !label && 'font-medium')}>{label || placeholder}</span>
          </Button>
        </PopoverTrigger>
        <PopoverContent
          data-slot="date-picker-content"
          className={cn('w-auto p-2', contentClassName)}
          align="start"
        >
          <Calendar
            mode={mode}
            selected={selected as never}
            onSelect={handleSelect}
            {...calendarProps}
          />
        </PopoverContent>
      </Popover>
    </div>
  )
}

export { DatePicker }
export type { DatePickerProps, DatePickerMode, DatePickerValue }

import { computed } from "vue";
import { normalizeProps, useMachine } from "@zag-js/vue";
import { datePickerConnect, datePickerMachine } from "@/lib/utils";
import type { DatePickerVueProps, DatePickerVueValue, DatePickerMode, DatePickerRangeValue } from "@/lib/utils";
import { getLocalTimeZone } from "@internationalized/date";
import { parse as parseDateValue } from "@zag-js/date-picker";
import type { DateValue } from "@zag-js/date-picker";
import type { Placement } from "@zag-js/popper";

export type UseDatePickerProps = DatePickerVueProps & {
    numberOfMonths?: number;
};

type DatePickerModelValue =
    | Date
    | {
        from?: Date;
        to?: Date;
    }
    | undefined;

export type UseDatePickerEmits = {
    (e: "update:modelValue", value: DatePickerModelValue): void;
    (e: "change", value: DatePickerModelValue): void;
};

export function useDatePicker(props: UseDatePickerProps, emit: UseDatePickerEmits) {
    const localTimeZone = getLocalTimeZone();
    const toPickerDate = (input: string | Date) =>
        parseDateValue(
            input instanceof Date
                ? `${input.getFullYear()}-${String(input.getMonth() + 1).padStart(2, "0")}-${String(
                    input.getDate()
                ).padStart(2, "0")}`
                : input
        );

    const toDateValueArray = (value: DatePickerVueValue | undefined, mode: DatePickerMode) => {
        if (!value) return undefined;
        if (value instanceof Date) return [toPickerDate(value)];

        const range = value as DatePickerRangeValue;
        if (mode === "range") {
            const parsed: DateValue[] = [];
            if (range?.from) parsed.push(toPickerDate(range.from));
            if (range?.to) parsed.push(toPickerDate(range.to));
            return parsed.length ? parsed : undefined;
        }

        const fallback = range?.from ?? range?.to;
        return fallback ? [toPickerDate(fallback)] : undefined;
    };

    const toModelValue = (values: DateValue[], mode: DatePickerMode) => {
        if (mode === "range") {
            const from = values[0]?.toDate(localTimeZone);
            const to = values[1]?.toDate(localTimeZone);
            return from || to ? { from, to } : undefined;
        }
        return values[0]?.toDate(localTimeZone);
    };

    const machineProps = computed(() => {
        const controlledValue =
            props.modelValue !== undefined
                ? toDateValueArray(props.modelValue, props.mode || "single")
                : undefined;

        const defaultValue =
            props.modelValue === undefined
                ? toDateValueArray(props.defaultValue, props.mode || "single")
                : undefined;

        return {
            selectionMode: props.mode || "single",
            numOfMonths: props.numberOfMonths || 1,
            outsideDaySelectable: true,
            timeZone: localTimeZone,
            value: controlledValue,
            defaultValue,
            onValueChange(details: { value: DateValue[] }) {
                const next = toModelValue(details.value, props.mode || "single");
                emit("update:modelValue", next);
                emit("change", next);
            },
            positioning: {
                placement: "bottom-start" as Placement,
                gutter: 6,
            },
        };
    });

    const service = useMachine(datePickerMachine, machineProps);
    const api = computed(() => datePickerConnect(service, normalizeProps));

    return {
        api,
        localTimeZone,
    };
}

import { cn } from '../utils'

Component({
  externalClasses: ['ext-class'],
  properties: {
    extClass: {
      type: String,
      value: '',
    },
  },
  data: {
    className: '',
  },
  observers: {
    extClass: function (extClass) {
      this.setData({
        className: cn('w-full', extClass),
      })
    },
  },
})
